package com.axiom.application.analysis;import com.axiom.domain.failure.FailureClassification;import java.util.*;import org.junit.jupiter.api.Test;import static org.assertj.core.api.Assertions.*;class PipelineTriageServiceTest{@Test void specificRootOutranksGenericExit(){var s=new PipelineTriageService();var r=s.triage(List.of(new PipelineTriageService.Failure("exit",FailureClassification.BUILD_FAILURE,true),new PipelineTriageService.Failure("oom",FailureClassification.RESOURCE_EXHAUSTION,false)),false,false);assertThat(r.primaryFingerprint()).isEqualTo("oom");assertThat(r.rerunRecommendation()).isEqualTo("CONSIDER");}@Test void infrastructureRerunIsRecommended(){assertThat(new PipelineTriageService().triage(List.of(new PipelineTriageService.Failure("db",FailureClassification.INFRASTRUCTURE_FAILURE,false)),true,false).rerunRecommendation()).isEqualTo("RECOMMENDED");}}
